handsontable(mtcars, rowHeaderWidth = 200)




# col & row specific config + validation + context menu:
handsontable(
  iris[1:8, ],
  adaptiveHeight = TRUE
) |&gt;
  hot_col(
    col = "Species",
    type = "dropdown",
    source = c("setosa", "versicolor", "virginica")
  ) |&gt;
  hot_validate(
    col = 1:4,
    type = "numeric",
    min = 0
  ) |&gt;
  hot_row(row = 6:7, readOnly = TRUE) |&gt;
  hot_context_menu()






